mapper.update:
update life_social.life_user
set login_count     = login_count + 1,
    last_login_time = #{now},
    last_login_ip   = #{clientIp}
where id = #{id}

mapper.select:
SELECT COUNT(1)
FROM life_social.life_user
WHERE deleted = 0 AND username = #{username}

SELECT COUNT(1)
FROM life_social.life_user
WHERE deleted = 0 AND phone = #{phone}

SELECT COUNT(1)
FROM life_social.life_user
WHERE deleted = 0 AND email = #{email}
